INSERT INTO Language_en_US(Tag,Text) VALUES
 ('TXT_KEY_CWC3_TIMETABLE_CIV','The Perpetual Timetable'),
 ('TXT_KEY_CWC3_TIMETABLE_SHORT','Perpetual Timetable'),
 ('TXT_KEY_CWC3_TIMETABLE_ADJECTIVE','Timetable'),
 ('TXT_KEY_CWC3_TIMETABLE_LEADER','Grand Stationmaster Veyl'),
 ('TXT_KEY_CWC3_TIMETABLE_TRAIT','The Grand Schedule'),
 ('TXT_KEY_CWC3_TIMETABLE_TRAIT_HELP','Non-capital cities connected to the Capital receive +1 [ICON_PRODUCTION] Production and +1 [ICON_RESEARCH] Science. After Railroad technology, non-capital cities connected by a continuous, fully owned, intact land railroad also receive +1 [ICON_CULTURE] Culture. Owned city centers act as junctions. Harbors qualify only for the ordinary connection bonuses.'),
 ('TXT_KEY_CWC3_TIMETABLE_CIV_PEDIA','The Perpetual Timetable believes that infrastructure creates prosperity. Every road, junction and station brings distant settlements into a shared schedule. Beneath monumental iron-and-glass vaults, engineers and administrators labor to connect the world. The World Shall Run on Time.'),
 ('TXT_KEY_CWC3_TIMETABLE_STRATEGY','Establish sensible settlements and ordinary city connections, including Harbors. Build Dispatch Offices, then research Railroad and upgrade to continuous railways entirely within your territory. Defend junctions and pursue Science, with Culture as a secondary victory.'),
 ('TXT_KEY_CWC3_TIMETABLE_LEADER_PEDIA','Grand Stationmaster Veyl is an elderly, disciplined railway administrator. Calm, precise, organized and generally friendly, he regards punctuality as the measure of civilization. His immaculate navy uniform bears locomotive-shaped medals, and his golden pocket watch governs every appointment.'),
 ('TXT_KEY_CWC3_TIMETABLE_UNIT','Line Surveyor'),
 ('TXT_KEY_CWC3_TIMETABLE_UNIT_HELP','Replaces the Worker. Retains all active Worker rules and construction actions, with +1 Movement and 10% higher Work Rate (rounded to the nearest integer). No early or free Railroads.'),
 ('TXT_KEY_CWC3_TIMETABLE_UNIT_PEDIA','Equipped with maps, measuring equipment and precision survey instruments, Line Surveyors turn ambitious plans into practical routes. Their efficient labor supports all ordinary improvements as well as roads and railways.'),
 ('TXT_KEY_CWC3_TIMETABLE_UNIT_STRATEGY','Use the extra Movement to reach new settlements and the higher Work Rate for every ordinary Worker action. Costs, maintenance, technology prerequisites and capture behavior follow the active Worker.'),
 ('TXT_KEY_CWC3_TIMETABLE_OFFICE','Dispatch Office'),
 ('TXT_KEY_CWC3_TIMETABLE_OFFICE_HELP','Replaces the Workshop and retains all its effects. Adds +1 [ICON_GOLD] Gold in every city. In non-capital Timetable cities, an ordinary Capital connection adds +1 [ICON_CULTURE] Culture; after Railroad technology a continuous, fully owned, intact land railroad adds +1 [ICON_PRODUCTION] Production. Conditional bonuses update at owner-turn evaluation for the following payout.'),
 ('TXT_KEY_CWC3_TIMETABLE_OFFICE_PEDIA','Beneath a great central clock tower, dispatchers coordinate railway schedules, industrial consignments and the daily work of a connected empire. Every arrival is recorded; every delay has an explanation.'),
 ('TXT_KEY_CWC3_TIMETABLE_OFFICE_STRATEGY','Build for all Workshop effects and unconditional Gold, even in the Capital. Connected non-capital Offices add Culture; complete owned railways add Production. Protect the infrastructure from pillaging.'),
 ('TXT_KEY_CWC3_TIMETABLE_DUMMY','Timetable Connection'),
 ('TXT_KEY_CWC3_TIMETABLE_DUMMY_HELP','Internal city-yield controller. Cannot be constructed or purchased.'),
 ('TXT_KEY_CWC3_TIMETABLE_GREETING_1','Welcome, esteemed visitor. Your appointment was scheduled for precisely 14:32. You have arrived at 14:31. Excellent. I approve.'),
 ('TXT_KEY_CWC3_TIMETABLE_WAR_1','Your civilization has repeatedly disrupted the proper functioning of international transportation. Regrettably, corrective measures are now scheduled.'),
 ('TXT_KEY_CWC3_TIMETABLE_ATTACKED_1','An invasion? Without submitting the appropriate scheduling documentation? OUTRAGEOUS.'),
 ('TXT_KEY_CWC3_TIMETABLE_DEFEAT_1','Impossible... our calculations... were perfect...'),
 ('TXT_KEY_CWC3_TIMETABLE_PEACE_1','Regular service may now resume. Let us keep to the agreed timetable.'),
 ('TXT_KEY_CWC3_TIMETABLE_FRIENDLY_1','Precisely on time. It is always a pleasure to receive a reliable colleague.'),
 ('TXT_KEY_CWC3_TIMETABLE_NEUTRAL_1','Your appointment is confirmed. Please proceed.'),
 ('TXT_KEY_CWC3_TIMETABLE_HOSTILE_1','These repeated disruptions are becoming most difficult to accommodate.'),
 ('TXT_KEY_CWC3_TIMETABLE_TRADE_1','The arrangements are satisfactory. Consider them entered into the schedule.'),
 ('TXT_KEY_CWC3_TIMETABLE_FALLBACK_1','Your proposal has been recorded. We shall give it our precise attention.'),
 ('TXT_KEY_CWC3_TIMETABLE_DAWN','Honorable Grand Stationmaster Veyl, Master of the Eternal Timetable, your people await your command.[NEWLINE][NEWLINE]Throughout history, civilizations have been divided by distance.[NEWLINE][NEWLINE]Mountains separated kingdoms. Rivers obstructed travelers. Vast wildernesses prevented the exchange of knowledge and prosperity.[NEWLINE][NEWLINE]Yet your people recognized a simple truth.[NEWLINE][NEWLINE]Distance is not an obstacle when every journey has a destination.[NEWLINE][NEWLINE]Through careful planning, tireless labor, and extraordinary engineering, your ancestors began connecting the scattered settlements of their homeland.[NEWLINE][NEWLINE]Roads became highways. Highways became railways. Railways became the arteries of a mighty civilization.[NEWLINE][NEWLINE]Now, the Perpetual Timetable stands ready to connect the world.[NEWLINE][NEWLINE]Establish your cities. Construct your transportation networks. Let every settlement contribute to the prosperity of your empire.[NEWLINE][NEWLINE]Will you build a civilization whose achievements endure throughout history?[NEWLINE][NEWLINE]Or will the world leave you behind?'),
 ('TXT_KEY_CWC3_TIMETABLE_CITY_1','Terminus Prime'),
